const headers={de:["Zeichnung lesen","G2A · Frästeil","Symbol wählen","Zeichnungsdetail, schematisch","Bezugssystem","B richtet das Werkstück aus. C legt die seitliche Lage fest. A ist die Auflagefläche.","Maße in mm. Abmaße sind Grenzabweichungen. Eckige Maße sind Bezugsmaße."],en:["Read the drawing","G2A · milled part","Choose a symbol","Drawing detail, schematic","Datum system","B orients the part. C locates it sideways. A is the seating face.","Dimensions in mm. Limit deviations are shown. Bracketed dimensions are reference dimensions."],ar:["قراءة الرسم","G2A · قطعة مفرزة","اختر رمزًا","تفصيل تخطيطي للرسم","نظام المراجع","يحدد B اتجاه القطعة. يحدد C موضعها الجانبي. أما A فهو سطح الإسناد.","الأبعاد بالملليمتر. الأبعاد بين أقواس مربعة مرجعية."]};
export function renderDrawingLesson(root,lang){
 const t=headers[lang]||headers.de, rows=entries[lang]||entries.de;
 root.innerHTML='<h2>'+t[0]+'</h2><p>'+t[1]+' · '+t[2]+'</p><div class="drawing-lesson"><figure><svg viewBox="0 0 640 330" role="img" aria-label="'+t[3]+'" direction="ltr"><path d="M70 90 H230 L315 175 V260 H70 Z M230 90 V155 H350 V260 M315 175 H510 V260 H315 M510 175 L565 120 H410" fill="none" stroke="#27263f" stroke-width="4"/><circle cx="175" cy="195" r="31" fill="none" stroke="#27263f" stroke-width="4"/><rect x="100" y="112" width="76" height="20" rx="10" fill="none" stroke="#27263f" stroke-width="4"/><circle cx="430" cy="215" r="15" fill="none" stroke="#27263f" stroke-width="4"/><circle cx="480" cy="215" r="15" fill="none" stroke="#27263f" stroke-width="4"/><path d="M70 270H510 M70 262V281 M510 262V281 M90 275H490 M550 125V260 M543 125H557 M543 260H557" fill="none" stroke="#006e73" stroke-width="2"/><text x="270" y="292" fill="#27263f" font-size="16">115</text><text x="563" y="200" fill="#27263f" font-size="16">50</text><text x="126" y="70" fill="#27263f" font-size="14">A</text><text x="180" y="270" fill="#27263f" font-size="14">B</text><text x="515" y="168" fill="#27263f" font-size="14">C</text><path d="M70 90L48 67 M230 90L250 66 M315 175L347 143 M430 200L456 172 M510 175L539 155" stroke="#6552df" stroke-width="2" stroke-dasharray="5 4"/></svg><figcaption>'+t[3]+'</figcaption><p>'+t[5]+'</p><p>'+t[6]+'</p></figure><section><h3>'+t[2]+'</h3>'+rows.map((r,i)=>'<button type="button" data-drawing-symbol="'+i+'" aria-pressed="'+(i===0)+'"><bdi>'+r[0]+'</bdi> '+r[1]+' · <bdi>'+r[2]+'</bdi></button>').join("")+'<article data-drawing-explanation aria-live="polite"><h3><bdi>'+rows[0][0]+'</bdi> '+rows[0][1]+'</h3><p>'+rows[0][3]+'</p><p>'+rows[0][4]+'</p></article></section></div><p>G2A · Teil 01 · EN AW 5083 · <a href="https://www.iso.org/standard/66777.html" target="_blank" rel="noopener">ISO 1101</a></p>';
 root.onclick=event=>{const b=event.target.closest("[data-drawing-symbol]");if(!b)return;const row=rows[Number(b.dataset.drawingSymbol)];root.querySelectorAll("[data-drawing-symbol]").forEach(x=>x.setAttribute("aria-pressed",String(x===b)));root.querySelector("[data-drawing-explanation]").innerHTML='<h3><bdi>'+row[0]+'</bdi> '+row[1]+'</h3><p>'+row[3]+'</p><p>'+row[4]+'</p>';};
}
